using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The MCP SDK discovers tools via [McpServerToolType] on the class
/// and [McpServerTool] on each method. Constructor parameters are
/// resolved from DI automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // DI injects a named/typed HttpClient configured in Program.cs
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/v1/current?city={Uri.EscapeDataString(city)}");

        return response is null
            ? $"No weather data found for {city}"
            : $"{city}: {response.Temperature}°C, {response.Condition}";
    }

    [McpServerTool, Description("Get a multi-day weather forecast")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-7)")] int days = 3)
    {
        var response = await _httpClient.GetFromJsonAsync<ForecastResponse>(
            $"/v1/forecast?city={Uri.EscapeDataString(city)}&days={days}");

        if (response?.Days is null or { Count: 0 })
            return $"No forecast available for {city}";

        var lines = response.Days.Select(d =>
            $"  {d.Date}: {d.High}°C / {d.Low}°C, {d.Condition}");
        return $"Forecast for {city}:\n{string.Join('\n', lines)}";
    }
}

// Response models
public record WeatherResponse(
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("condition")] string Condition);

public record ForecastDay(
    [property: JsonPropertyName("date")] string Date,
    [property: JsonPropertyName("high")] double High,
    [property: JsonPropertyName("low")] double Low,
    [property: JsonPropertyName("condition")] string Condition);

public record ForecastResponse(
    [property: JsonPropertyName("days")] List<ForecastDay> Days);

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using ModelContextProtocol;

var builder = McpServerBuilder.ForStdioTransport();

builder.ServerInfo = new() { Name = "weather-mcp", Version = "1.0.0" };

// Register HttpClient for WeatherTools via DI
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

// Register all [McpServerToolType] classes from this assembly
builder.WithTools();

await using var server = builder.Build();
await server.RunAsync();

