using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The MCP SDK discovers tools via [McpServerToolType] on the class
/// and [McpServerTool] on each method. Constructor parameters are
/// resolved from DI automatically.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // DI injects a named/typed HttpClient configured in Program.cs
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city)
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/v1/current?city={Uri.EscapeDataString(city)}");

        return response is null
            ? $"No weather data found for {city}"
            : $"{city}: {response.Temperature}°C, {response.Condition}";
    }

    [McpServerTool, Description("Get a multi-day weather forecast")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of days (1-7)")] int days = 3)

